  Test("one-shot setter failure retries then releases registry",()=>{var t=Plain(new(2,2,1));t.FailWrite=true;Scope.ApplyOneShotAllWorlds(t,new(1,1,1),new(1,1,1));Vector(new(2,2,1),t.localScale);Eq(1,RegistryCount(),"pending retained");Retry();Vector(new(1,1,1),t.localScale);Eq(0,RegistryCount(),"released after correction");});
  Test("one-shot committed setter throw finalizes without rewrite",()=>{var t=Plain(new(2,2,1));int writes=t.Writes;t.FailWrite=true;t.CommitBeforeFailure=true;Scope.ApplyOneShotAllWorlds(t,new(1,1,1),new(1,1,1));Vector(new(1,1,1),t.localScale);Eq(writes+1,t.Writes,"one committed write");Eq(1,RegistryCount(),"pending until observed");Retry();Eq(writes+1,t.Writes,"no retry write");Eq(0,RegistryCount(),"released");});
  Test("one-shot read fault defers pending transaction",()=>{var t=Plain(new(2,2,1));t.FailWrite=true;t.CommitBeforeFailure=true;Scope.ApplyOneShotAllWorlds(t,new(1,1,1),new(1,1,1));t.FailReads=1;int writes=t.Writes;Retry();Eq(writes,t.Writes,"no write during read fault");Eq(1,RegistryCount(),"pending kept");Retry();Eq(writes,t.Writes,"committed write not repeated");Eq(0,RegistryCount(),"released after readable retry");});
